        self._validate_str(role, "role")
        self._validate_iterable_of_str(parents, "parents")

        # Normalise parents to a list (empty if None)
        parent_list = list(parents or [])

        # Temporarily add the role to the graph to test for cycles
        original_parents = self.roles.get(role, None)
        self.roles[role] = parent_list

        try:
            # Perform a DFS from the new role to detect a back‑edge to itself
            def dfs(current, visited, stack):
                visited.add(current)
                stack.add(current)
                for p in self.roles.get(current, []):
