        This method assumes cycles have been prevented during role addition,
        but still guards against unexpected recursion by tracking visited nodes.
        """
        if _visited is None:
            _visited = set()
        if role in _visited:
            # Defensive guard – should never happen if cycle detection works.
            return set()
        _visited.add(role)
        res = {role}
        for parent in self.roles.get(role, []):
            res.update(self._get_all_roles(parent, _visited))
        return res

    def evaluate(self, user: str, permission: str) -> bool:
        """Evaluate whether *user* is allowed the *permission*.

        The algorithm follows a deny‑by‑default policy with explicit DENY
        taking precedence over any ALLOW. If the permission is not defined for
        any of the user's roles (including inherited roles), the result is
        ``False``.
        """
        self._validate_str(user, "user")
        self._validate_str(permission, "permission")

        # Gather all roles reachable from the user's direct assignments.
        roles: set[str] = set()
        for direct_role in self.user_roles.get(user, set()):
            roles.update(self._get_all_roles(direct_role))

        # First check for any explicit DENY; if found, deny immediately.
        for r in roles:
            effect = self.permissions.get(r, {}).get(permission)
            if effect == "DENY":
                return False

        # If no DENY, check for any ALLOW.
        for r in roles:
            effect = self.permissions.get(r, {}).get(permission)
            if effect == "ALLOW":
                return True

        # Default deny.
        return False
