selected_edits.content:
"""RBAC Policy Engine with strict validation, role inheritance, deny‑overrides‑allow semantics, and cycle detection.

The engine is deliberately deny‑by‑default.  Permissions are evaluated across a user's direct roles and all ancestor roles.  If any role explicitly DENYs a permission the evaluation returns ``False`` even if other roles ALLOW it.  Cyclic role inheritance is prohibited and raises ``CyclicRoleInheritanceError``.

All public mutating methods perform exhaustive type and value checks and operate atomically – any validation error leaves the engine's internal state unchanged.
"""

from __future__ import annotations

from copy import deepcopy
from typing import Dict, List, Set


class CyclicRoleInheritanceError(Exception):
    """Raised when adding a role would introduce a cycle in the inheritance graph."""

    pass


class RBACPolicyEngine:
    """In‑memory RBAC engine.

    * ``roles`` maps a role name to a list of its parent role names.
    * ``permissions`` maps a role name to a dict of ``permission -> effect`` where effect is ``"ALLOW"`` or ``"DENY"``.
    * ``user_roles`` maps a user identifier to a set of directly‑assigned role names.
    """

    def __init__(self) -> None:
        self.roles: Dict[str, List[str]] = {}
        self.permissions: Dict[str, Dict[str, str]] = {}
        self.user_roles: Dict[str, Set[str]] = {}

    # ---------------------------------------------------------------------
    # Helper validation utilities
    # ---------------------------------------------------------------------
    @staticmethod
    def _validate_str(value: object, name: str) -> str:
        if not isinstance(value, str) or isinstance(value, bool) or not value:
            raise ValueError(f"{name} must be a non‑empty string")
        return value

    @staticmethod
    def _validate_str_list(value: object, name: str) -> List[str]:
        if value is None:
            return []
        if not isinstance(value, (list, tuple)):
            raise ValueError(f"{name} must be a list or tuple of strings")
        result = []
        for i, item in enumerate(value):
            if not isinstance(item, str) or isinstance(item, bool) or not item:
                raise ValueError(f"{name}[{i}] must be a non‑empty string")
            result.append(item)
        return result

    @staticmethod
    def _validate_effect(value: object) -> str:
        if not isinstance(value, str) or isinstance(value, bool):
            raise ValueError("effect must be a string")
        if value not in ("ALLOW", "DENY"):
            raise ValueError("effect must be either 'ALLOW' or 'DENY'")
        return value

    # ---------------------------------------------------------------------
    # Core API
    # ---------------------------------------------------------------------
    def add_role(self, role: object, parents: object = None) -> None:
        """Add a role with optional parent roles.

        The operation is atomic – if validation fails or a cycle would be created the engine's state is left untouched.
        """
        role_name = self._validate_str(role, "role")
        parent_names = self._validate_str_list(parents, "parents")

        # Preserve original state for rollback on failure
        old_roles = deepcopy(self.roles)
        old_permissions = deepcopy(self.permissions)

        try:
            # Register role and its parents
            self.roles[role_name] = list(parent_names)
            if role_name not in self.permissions:
                self.permissions[role_name] = {}

            # Detect cycles using DFS
            visited: Set[str] = set()
            stack: Set[str] = set()

            def dfs(node: str) -> None:
                if node in stack:
                    raise CyclicRoleInheritanceError(f"Cyclic inheritance detected involving role '{node}'")
                if node in visited:
                    return
                visited.add(node)
                stack.add(node)
                for parent in self.roles.get(node, []):
                    dfs(parent)
                stack.remove(node)

            for r in self.roles:
                dfs(r)
        except Exception:
            # Roll back to the original state before re‑raising
            self.roles = old_roles
            self.permissions = old_permissions
            raise

    def assign_permission(self, role: object, permission: object, effect: object = "ALLOW") -> None:
        """Assign a permission to a role with the given effect.

        ``effect`` must be either ``"ALLOW"`` or ``"DENY"``.  The operation is atomic.
        """
        role_name = self._validate_str(role, "role")
        perm_name = self._validate_str(permission, "permission")
        eff = self._validate_effect(effect)

        if role_name not in self.roles:
            raise ValueError(f"Role '{role_name}' does not exist")

        # Atomic update – copy only the affected role's permission dict
        old_perm_dict = deepcopy(self.permissions.get(role_name, {}))
        try:
            self.permissions.setdefault(role_name, {})[perm_name] = eff
        except Exception:
            self.permissions[role_name] = old_perm_dict
            raise

    def assign_user_role(self, user: object, role: object) -> None:
        """Assign a role to a user.

        Both ``user`` and ``role`` must be non‑empty strings.  The role must exist.
        """
        user_name = self._validate_str(user, "user")
        role_name = self._validate_str(role, "role")

        if role_name not in self.roles:
            raise ValueError(f"Role '{role_name}' does not exist")

        # Atomic update of the user's role set
        old_set = deepcopy(self.user_roles.get(user_name, set()))
        try:
            self.user_roles.setdefault(user_name, set()).add(role_name)
        except Exception:
            if old_set:
                self.user_roles[user_name] = old_set
            else:
                self.user_roles.pop(user_name, None)
